method.description:
[method NetwMultiplayer.transport_create_peer] with [param transport] named the way every verb on this view names one: the peer class itself, a game transport's [Script], a [StringName], or a live peer of that class. That document carries the law, and it is short: [param completed] runs once in a later frame as [code]completed(peer, error, detail)[/code], and [b]the peer is assigned inside it, before it returns[/b]. Returning without assigning declines the offer, and the session closes the peer.
The result is a [RID] and it is the one on this view. It is the ticket [method cancel_peer_creation] consumes, and it is a bridge rather than an identity: it is write-once, use-once, it has no name and no pair to be spelled by, and it retires itself the moment [param completed] has run. Everything else this view returns is a [Dictionary] or a [bool], and everything it takes is named on the [Variant] axis.
[codeblock]
var _ticket := RID()

func join(address: String) -> void:
    abort_join()
    _ticket = _c.create_peer(
            MyRelayTransport,
            NetwMultiplayer.TRANSPORT_MODE_CLIENT,
            address, {}, _created, _progressed)

func abort_join() -> void:
    _c.cancel_peer_creation(_ticket)
    _ticket = RID()

func _created(peer: MultiplayerPeer, error: Error, detail: String):
    _ticket = RID()
    if error == OK:
        Netw.of(self).multiplayer_peer = peer
    elif error != ERR_SKIP:
        _say(detail)
[/codeblock]
